import{_ as o,l as i,o as e,c as n,v as t,p as l,x as r,d as p,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"超标量发射","description":"","frontmatter":{"title":"超标量发射","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/superscalar-issue.md","filePath":"cs/superscalar-issue.md","lastUpdated":1789023840000}'),h={name:"cs/superscalar-issue.md"};function E(u,a,_,A,m,B){const s=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="超标量发射" tabindex="-1">超标量发射 <a class="header-anchor" href="#超标量发射" aria-label="Permalink to &quot;超标量发射&quot;">​</a></h1><div class="epigraph"><p>理想 CPI 已经是 1 时，再降时间只能每拍取出并启动多于一条指令。</p><footer>—— 据 Hennessy and Patterson, Computer Architecture: A Quantitative Approach 整理</footer></div><p><a href="/cs/coherence-intro">上一课</a>指出多副本尚未有协议，但单核流水线的 CPI 公式已经够用。<a href="/cs/coherence-intro">CPI 与阿姆达尔</a>把理想项钉在 1。<a href="/cs/pipeline-five-stage">流水线五级</a>每拍推进一级、每拍取一条。本课不重讲转发。缺口是：指令级并行若存在，硬件每拍仍只发射一条，吞吐封顶。本课只交出超标量：每拍译码并发射最多 \\(W\\) 条，理想 CPI 变成 \\(1/W\\)。一致性协议仍未实现，本课不靠多核。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>程序里相邻指令常常不相关：一条在 ALU，一条在访存。五级顺序发射把它们排成一列。缺口不是更长的流水线（那只提高频率、加深控制冒险），而是<strong>加宽取指/译码/发射</strong>，让独立指令进入不同功能单元。</p><p>结构冒险回来了：每拍可能要两个 ALU、两个寄存器读口、两条 cache 端口。上一课的一致性问题在单核超标量里仍可搁置；端口不够则不能真的双发。</p><p><span class="marginnote">超标量是每拍多条标量指令；SIMD 是一条指令多条数据，后课才拆开。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>取指带宽加到 \\(W\\) 条，译码检查这 \\(W\\) 条之间以及与已在流水线中指令的 RAW。可同时发射的送进对应单元；相关则只发前缀，或整组停顿。仍保持程序序发射：更年轻的不得越过年长且相关的。</p>',9)),(e(),l(d,null,{default:r(()=>[c(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20LR%0A%20%20F%5B%22%E5%8F%96%20W%20%E6%9D%A1%22%5D%20--%3E%20D%5B%22%E8%AF%91%E7%A0%81%E4%B8%8E%E7%9B%B8%E5%85%B3%E6%A3%80%E6%9F%A5%22%5D%0A%20%20D%20--%3E%20I0%5B%22%E5%8F%91%E5%B0%84%E5%88%B0%20ALU%22%5D%0A%20%20D%20--%3E%20I1%5B%22%E5%8F%91%E5%B0%84%E5%88%B0%E8%AE%BF%E5%AD%98%22%5D%0A%20%20D%20--%3E%20ST%5B%22%E7%9B%B8%E5%85%B3%EF%BC%9A%E5%B0%91%E5%8F%91%E6%88%96%E4%B8%8D%E5%8F%91%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>寄存器堆读口、cache 端口按 \\(W\\) 复制。控制冒险的损失拍数若不变，每拍扔掉的指令变多，预测更重要。本课不引入乱序执行。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>IPC 上限为 \\(W\\)，实际受依赖、分支、缺失限制。阿姆达尔仍适用：不能双发的那部分代码把平均 IPC 往 1 拉。编译器调度可以拉开相关距离，让窗口内更常填满 \\(W\\)；硬件必须在任意二元组上正确。</p><p>精确异常仍按程序序：即使两条同拍发射，提交仍要像顺序机。顺序超标量可以用「两条都过提交点才一起写」或按序写回。乱序才是下一课。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入重命名、保留站、ROB。也不把发射宽度写成「核数」：那是多核课。VLIW 把打包交给编译器，主干不转向。</p><p>后课默认：单核可以每拍尝试发射多于一条；相关与缺失仍按五级那套检测，只是端口变多。真正把后面独立指令提到前面，靠乱序。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>理想 CPI 从 1 降到 \\(1/W\\) 需要每拍发射最多 \\(W\\) 条。</li><li>顺序超标量仍按程序序发射；结构端口必须加宽。</li><li>乱序与 ROB 是下一课的缺口。</li><li>出处：Hennessy and Patterson, <em>CA:AQA</em> 指令级并行与超标量。</li></ul>',9))])}const C=o(h,[["render",E]]);export{P as __pageData,C as default};
